/**
 * From detector output to an explained, actionable finding.  Rule-based and auditable: every
 * finding names the rule that produced it (shared/rules.json) and the countermeasure sources
 * (shared/countermeasures.json).  No text here is generated by a language model.
 */
import rulesJson from '../../../shared/rules.json'
import cmJson from '../../../shared/countermeasures.json'
import refsJson from '../../../shared/references.json'
import { concernDev, deployedScore, episodes, inverseTransform, type ModelJson } from './detect'
import { IND, phaseAt, rawSeries, SYM, symptomsOn } from './mission'
import type { Change, CrewAnalysis, Entry, Factor, Finding, Mission, Status, Tier } from './types'

export interface Countermeasure { id: string; title: string; type: string; refs: string[]; text: string }
export const COUNTERMEASURES = cmJson as Countermeasure[]
export const CM: Record<string, Countermeasure> = Object.fromEntries(COUNTERMEASURES.map((c) => [c.id, c]))
export const REFS = refsJson as Record<string, { text: string; url: string | null }>

type Cond =
  | { u: string; min: number }
  | { u: string; max: number }
  | { sym: string; min: number }
  | { env: string; min: number }
  | { phase_days_max: number }
  | { phase_days_min: number }
  | { alert_days_min: number }
  | { always: boolean }
  | { all: Cond[] }
  | { any: Cond[] }

export interface Rule {
  id: string
  scope: 'personal' | 'environment' | 'symptom' | 'adaptation'
  priority: number
  title: string
  when: Cond
  summary: string
  action: string
  steps: string[]
  tier: Tier
  tier_reason: string
  cm: string[]
  categories: string[]
  escalate?: { when: Cond; tier: Tier; reason: string }[]
}
export const RULES = (rulesJson.rules as unknown as Rule[]).slice().sort((a, b) => a.priority - b.priority)
export const RULE: Record<string, Rule> = Object.fromEntries(RULES.map((r) => [r.id, r]))

export interface RuleFeatures {
  u: Record<string, number>
  sym: Record<string, number>
  env: Record<string, number>
  phaseDays: number
  hasPhase: boolean
  alertDays: number
}

export function evalCond(c: Cond, f: RuleFeatures): boolean {
  if ('all' in c) return c.all.every((x) => evalCond(x, f))
  if ('any' in c) return c.any.some((x) => evalCond(x, f))
  if ('u' in c && 'max' in c) return !((f.u[c.u] ?? -Infinity) > c.max)
  if ('u' in c) return (f.u[c.u] ?? -Infinity) >= c.min
  if ('sym' in c) return (f.sym[c.sym] ?? 0) >= c.min
  if ('env' in c) return (f.env[c.env] ?? -Infinity) >= c.min
  if ('phase_days_max' in c) return f.hasPhase && f.phaseDays <= c.phase_days_max
  if ('phase_days_min' in c) return f.hasPhase && f.phaseDays >= c.phase_days_min
  if ('alert_days_min' in c) return f.alertDays >= c.alert_days_min
  if ('always' in c) return true
  return false
}

/** Indicators a rule's condition refers to (they are shown first as the evidence for that rule). */
export function condIndicators(c: Cond): string[] {
  if ('all' in c) return c.all.flatMap(condIndicators)
  if ('any' in c) return c.any.flatMap(condIndicators)
  if ('u' in c && 'min' in c) return [c.u]
  return []
}

const TIER_RANK: Record<Tier, number> = { self: 0, cmo: 1, ground: 2 }

export function applyRule(r: Rule, f: RuleFeatures): { tier: Tier; reason: string } {
  let tier = r.tier
  let reason = r.tier_reason
  for (const e of r.escalate ?? []) {
    if (TIER_RANK[e.tier] > TIER_RANK[tier] && evalCond(e.when, f)) {
      tier = e.tier
      reason = e.reason
    }
  }
  return { tier, reason }
}

const mean = (v: number[]) => (v.length ? v.reduce((a, b) => a + b, 0) / v.length : NaN)
const lastValid = (v: number[], day: number, back = 3) => {
  for (let t = day; t > day - back && t >= 0; t--) if (!Number.isNaN(v[t])) return v[t]
  return NaN
}

export interface DayAnalysis {
  status: Status
  findings: Finding[]
  /** indicators that moved, most unusual first (shown even when no alert is open) */
  changes: Change[]
  learning: boolean
  baselineDays: number
  adapting: { name: string; day: number } | null
  u3: Record<string, number>
  systems: Record<string, Status>
  alert: { start: number; days: number; tier: 'notice' | 'alert'; score: number } | null
  features: RuleFeatures
}

export const TIER_LABEL: Record<Tier, string> = {
  self: 'Manage it yourself',
  cmo: 'Inform the crew medical officer',
  ground: 'Contact the ground when a link is available',
}

export const STATUS_LABEL: Record<Status, string> = {
  learning: 'Learning your normal',
  steady: 'Steady',
  watch: 'Worth a look',
  act: 'Act today',
  urgent: 'Act now',
}

export function analyzeDay(
  m: Mission, crewId: string, an: CrewAnalysis, model: ModelJson, day: number, entries: Entry[],
): DayAnalysis {
  const ids = model.indicators
  const p = model.params
  const sc = an.scored
  const d = ids.length
  const uAt = (t: number, j: number) => concernDev(sc.z[t]?.[j] ?? NaN, model.concern[j])

  // --- three-day deviation per indicator -------------------------------------------------
  const u3: Record<string, number> = {}
  for (let j = 0; j < d; j++) {
    const v: number[] = []
    for (let t = Math.max(0, day - 2); t <= day; t++) if (!Number.isNaN(uAt(t, j))) v.push(uAt(t, j))
    u3[ids[j]] = mean(v)
  }
  const baselineDays = sc.z.slice(0, day + 1).filter((r) => r.some((v) => !Number.isNaN(v))).length
  const learning = baselineDays < 3

  // --- what changed ------------------------------------------------------------------------
  const changes: Change[] = []
  for (let j = 0; j < d; j++) {
    const id = ids[j]
    const uu = u3[id]
    if (!(uu >= 1.2)) continue
    const raw = rawSeries(m, crewId, id, entries)
    const tLast = [day, day - 1, day - 2].find((t) => t >= 0 && !Number.isNaN(sc.z[t][j]))
    if (tLast === undefined) continue
    const mt = sc.m[tLast][j]
    const st = sc.s[tLast][j]
    const tr = model.transform[j]
    let daysOut = 0
    for (let t = day; t >= 0; t--) {
      const q = uAt(t, j)
      if (Number.isNaN(q)) continue
      if (q >= 1.2) daysOut++
      else break
    }
    const hist: number[] = []
    for (let t = Math.max(0, day - 60); t < day - 2; t++) if (!Number.isNaN(uAt(t, j))) hist.push(uAt(t, j))
    const pct = hist.length >= 10 ? hist.filter((h) => h < uu).length / hist.length : NaN
    changes.push({
      ind: id, value: raw[tLast], expected: inverseTransform(mt, tr),
      lo: inverseTransform(mt - 2 * st, tr), hi: inverseTransform(mt + 2 * st, tr),
      u3: uu, z: sc.z[tLast][j], direction: sc.z[tLast][j] >= 0 ? 'higher' : 'lower', percentile: pct, daysOut,
    })
  }
  changes.sort((a, b) => b.u3 - a.u3)

  // --- symptoms, environment, phase --------------------------------------------------------
  const sym: Record<string, number> = {}
  for (let t = Math.max(0, day - 2); t <= day; t++) for (const s of symptomsOn(m, crewId, t, entries)) sym[s] = (sym[s] ?? 0) + 1
  const co2 = rawSeries(m, crewId, 'co2', entries)
  const rad = rawSeries(m, crewId, 'rad', entries)
  const co23 = mean(co2.slice(Math.max(0, day - 2), day + 1).filter((v) => !Number.isNaN(v)))
  const radHist = rad.slice(Math.max(m.pre_days, day - 30), Math.max(0, day - 1)).filter((v) => !Number.isNaN(v)).sort((a, b) => a - b)
  const radMed = radHist.length >= 5 ? radHist[Math.floor(radHist.length / 2)] : NaN
  const env: Record<string, number> = { co2_3d: co23, co2: lastValid(co2, day), rad: lastValid(rad, day), rad_ratio: lastValid(rad, day) / radMed }
  const ph = phaseAt(m, day)
  const hasPhase = m.phases.some((q) => day >= q.start)
  const adapting = hasPhase && ph.since < 14 ? { name: ph.name, day: ph.since + 1 } : null

  // --- detector state ----------------------------------------------------------------------
  const eps = episodes(deployedScore(sc, model), model.thresholds.notice, p.merge_gap, day)
  const last = eps[eps.length - 1]
  let alert: DayAnalysis['alert'] = null
  if (last && day - last[1] <= p.merge_gap) {
    let peak = 0
    for (let t = last[0]; t <= day; t++) if (deployedScore(sc, model)[t] > peak) peak = deployedScore(sc, model)[t]
    alert = { start: last[0], days: day - last[0] + 1, tier: peak >= model.thresholds.alert ? 'alert' : 'notice', score: peak }
  }
  const f: RuleFeatures = { u: u3, sym, env, phaseDays: ph.since, hasPhase, alertDays: alert?.days ?? 0 }

  // --- contributing factors from the person's own recent data ---------------------------
  const factors: Factor[] = []
  const val3 = (id: string) => mean(rawSeries(m, crewId, id, entries).slice(Math.max(0, day - 2), day + 1).filter((v) => !Number.isNaN(v)))
  const exp = (id: string) => {
    const j = ids.indexOf(id)
    return j < 0 ? NaN : inverseTransform(sc.m[day]?.[j] ?? NaN, model.transform[j])
  }
  const f1 = (v: number, dgt = 1) => (Number.isNaN(v) ? '–' : v.toFixed(dgt))
  if (u3.sleep_h >= 1) factors.push({ id: 'sleep', text: 'Short sleep', evidence: `Sleep averaged ${f1(val3('sleep_h'))} h over the last three nights; your normal is ${f1(exp('sleep_h'))} h.` })
  if (u3.sleep_mid >= 1.5) factors.push({ id: 'timing', text: 'Sleep timing moved', evidence: `Your sleep period has shifted about ${f1(Math.abs(val3('sleep_mid') - exp('sleep_mid')))} h from where it usually sits.` })
  if (u3.fluid >= 1) factors.push({ id: 'fluid', text: 'Low fluid intake', evidence: `You logged ${f1(val3('fluid'))} L a day over the last three days; your normal is ${f1(exp('fluid'))} L.` })
  if (u3.ex7 >= 1) factors.push({ id: 'exercise', text: 'Less exercise than usual', evidence: `Seven-day average ${f1(lastValid(rawSeries(m, crewId, 'ex7', entries), day), 0)} min a day against your usual ${f1(exp('ex7'), 0)}.` })
  {
    const ex = rawSeries(m, crewId, 'ex_min', entries)
    const y = ex[day - 1]
    const usual = exp('ex7')
    if (!Number.isNaN(y) && !Number.isNaN(usual) && y > usual * 1.4 + 20) factors.push({ id: 'load', text: 'Hard session yesterday', evidence: `Yesterday's exercise was ${f1(y, 0)} min, well above your usual ${f1(usual, 0)}. Heart rate often runs higher the night after.` })
  }
  if (u3.energy >= 1) factors.push({ id: 'food', text: 'Eating less than planned', evidence: `About ${f1(val3('energy'), 0)}% of plan over the last three days; your normal is ${f1(exp('energy'), 0)}%.` })
  if (u3.mood >= 1) factors.push({ id: 'mood', text: 'Lower mood', evidence: `Mood check-ins averaged ${f1(val3('mood'))} of 5; your normal is ${f1(exp('mood'))}.` })
  if (co23 >= 2.5) factors.push({ id: 'co2', text: 'Cabin carbon dioxide', evidence: `Cabin CO2 averaged ${f1(co23)} mmHg over three days. Headache risk rises above 2.5 mmHg.` })
  const symList = Object.keys(sym).filter((s) => s in SYM)
  if (symList.length) factors.push({ id: 'symptoms', text: 'Symptoms you reported', evidence: symList.map((s) => `${SYM[s].label.toLowerCase()} (${sym[s]} of the last 3 days)`).join(', ') + '.' })
  if (adapting) factors.push({ id: 'phase', text: 'Recent gravity change', evidence: `Day ${adapting.day} of ${adapting.name.toLowerCase()}. Keel expects readings to move during adaptation and has widened your ranges.` })

  // --- rules ---------------------------------------------------------------------------------
  const findings: Finding[] = []
  const mk = (r: (typeof RULES)[number], kind: Finding['kind'], start: number, status: Status, ch: Change[], extra: Partial<Finding> = {}): Finding => {
    const t = applyRule(r, f)
    return {
      key: `${m.id}|${kind === 'environment' ? 'crew' : crewId}|${kind === 'personal' ? 'P' : r.id}|${start}`, kind, crewWide: kind === 'environment', status, start,
      days: day - start + 1, ruleId: r.id, title: r.title, summary: r.summary, changes: ch, factors: kind === 'personal' ? factors : factors.filter((x) => x.id === 'co2' || x.id === 'symptoms' || x.id === 'phase'),
      action: r.action, steps: r.steps, tier: t.tier, tierReason: t.reason, countermeasures: r.cm, categories: r.categories, ...extra,
    }
  }
  const firstDay = (test: (t: number) => boolean) => {
    let s = day
    while (s > 0 && test(s - 1)) s--
    return s
  }
  for (const r of RULES) {
    if (r.scope === 'symptom' && evalCond(r.when, f)) findings.push(mk(r, 'symptom', day, 'urgent', []))
    if (r.scope === 'environment' && day >= m.pre_days && evalCond(r.when, f)) {
      const start = r.id === 'R-CO2'
        ? firstDay((t) => mean(co2.slice(Math.max(0, t - 2), t + 1).filter((v) => !Number.isNaN(v))) >= 3.0)
        : firstDay((t) => rad[t] / radMed >= 3)
      const ind = r.id === 'R-CO2' ? 'co2' : 'rad'
      const v = env[ind]
      findings.push(mk(r, 'environment', start, 'act', [{ ind, value: v, expected: r.id === 'R-CO2' ? 2.5 : radMed, lo: 0, hi: r.id === 'R-CO2' ? 3.0 : radMed * 3, u3: NaN, z: NaN, direction: 'higher', percentile: NaN, daysOut: day - start + 1 }]))
    }
    if (r.scope === 'adaptation' && evalCond(r.when, f)) findings.push(mk(r, 'adaptation', Math.max(0, day - ph.since), 'watch', []))
  }
  if (alert && !learning) {
    const r = RULES.find((q) => q.scope === 'personal' && evalCond(q.when, f)) ?? RULE['R-GEN']
    const t = applyRule(r, f)
    // Escalation beyond self-management needs the stricter detector tier (its own, smaller
    // false-alert budget) or a symptom the crew member reported themselves.
    const corroborated = alert.tier === 'alert' || symList.some((s) => ['sore_throat', 'nausea', 'dizziness', 'vision'].includes(s))
    const early = t.tier !== 'self' && !corroborated
    const status: Status = alert.tier === 'alert' || (t.tier !== 'self' && corroborated) ? 'act' : 'watch'
    const named = condIndicators(r.when)
    const evidence = [...changes.filter((c) => named.includes(c.ind)), ...changes.filter((c) => !named.includes(c.ind))].slice(0, 4)
    const cats = new Set<string>([...r.categories, ...evidence.map((c) => IND[c.ind]?.category ?? 'cardio')])
    findings.push(mk(r, 'personal', alert.start, status, evidence, {
      score: alert.score, threshold: model.thresholds.notice, categories: [...cats], detectorTier: alert.tier,
      ...(early ? { tier: 'self' as Tier, tierReason: 'Early signal. Keel will suggest involving the medical officer if it strengthens, lasts, or you report symptoms.', action: r.action.replace(/,? and tell the medical officer\.$/, '.') } : {}),
    }))
  }
  const rank: Record<Status, number> = { urgent: 4, act: 3, watch: 2, steady: 1, learning: 0 }
  findings.sort((a, b) => rank[b.status] - rank[a.status])
  const status: Status = findings.length ? findings[0].status : learning ? 'learning' : 'steady'

  // --- body systems --------------------------------------------------------------------------
  const systems: Record<string, Status> = {}
  for (const id of ids) {
    const sysId = IND[id].system
    const uu = u3[id]
    const st: Status = Number.isNaN(uu) ? 'learning' : uu >= 2.5 ? 'act' : uu >= 1.5 ? 'watch' : 'steady'
    if (!(sysId in systems) || rank[st] > rank[systems[sysId]]) systems[sysId] = st
  }
  systems.environment = findings.some((x) => x.kind === 'environment') ? 'act' : co23 >= 2.5 ? 'watch' : 'steady'

  return { status, findings, changes, learning, baselineDays, adapting, u3, systems, alert, features: f }
}

/** Plain-language sentence for one change. */
export function describeChange(c: Change): string {
  const def = IND[c.ind]
  const d = def.decimals
  const v = Number.isNaN(c.value) ? '–' : c.value.toFixed(d)
  if (Number.isNaN(c.u3)) return `${def.label} is ${v} ${def.unit}.`
  const dir = c.ind === 'sleep_mid' ? 'shifted' : c.direction
  return `${def.label} is ${dir === 'shifted' ? 'shifted' : dir + ' than your normal'}: ${v} ${def.unit} against your usual ${c.expected.toFixed(d)}.`
}

export function unusualness(c: Change): string {
  if (Number.isNaN(c.percentile)) return 'Not enough history yet to say how unusual this is for you.'
  const pct = Math.round(c.percentile * 100)
  const days = c.daysOut > 1 ? ` It has been outside your usual range for ${c.daysOut} days.` : ''
  if (pct >= 99) return `More unusual than any of your last 60 days.${days}`
  return `More unusual than ${pct}% of your last 60 days.${days}`
}
